1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { subscribe, type SubscribeResult } from "@/lib/actions-newsletter";
5	import { IconMail, IconArrow, IconCheck } from "./icons";
6	
7	type Variant = "footer" | "inline";
8	
9	/**
10	 * Email capture that calls the `subscribe` server action directly. Shows a
11	 * friendly inline status for success / already-subscribed / validation errors.
12	 * `variant` only tweaks layout — logic is shared.
13	 */
14	export function NewsletterSignup({
15	  source = "landing",
16	  variant = "footer",
17	}: {
18	  source?: string;
19	  variant?: Variant;
20	}) {
21	  const [email, setEmail] = useState("");
22	  const [result, setResult] = useState<SubscribeResult | null>(null);
23	  const [pending, startTransition] = useTransition();
24	
25	  const succeeded = result?.ok === true;
26	
27	  function onSubmit(e: React.FormEvent) {
28	    e.preventDefault();
29	    if (pending) return;
30	    startTransition(async () => {
31	      const res = await subscribe(email, source);
32	      setResult(res);
33	      if (res.ok) setEmail("");
34	    });
35	  }
36	
37	  return (
38	    <form onSubmit={onSubmit} noValidate className={variant === "inline" ? "mx-auto max-w-md" : "w-full"}>
39	      <div className="flex flex-col gap-2.5 sm:flex-row">
40	        <div className="relative flex-1">
41	          <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">
42	            <IconMail size={18} />
43	          </span>
44	          <input
45	            type="email"
46	            name="email"
47	            autoComplete="email"
48	            required
49	            value={email}
50	            onChange={(e) => setEmail(e.target.value)}
51	            placeholder="you@example.com"
52	            aria-label="Email address"
53	            aria-invalid={result?.ok === false || undefined}
54	            className="input w-full pl-10"
55	            disabled={pending}
56	          />
57	        </div>
58	        <button
59	          type="submit"
60	          className="btn-primary shrink-0 justify-center px-5 py-2.5"
61	          disabled={pending}
62	        >
63	          {pending ? "Subscribing…" : "Subscribe"}
64	          {!pending && <IconArrow size={16} />}
65	        </button>
66	      </div>
67	
68	      {result && (
69	        <p
70	          className={`mt-2.5 flex items-center gap-1.5 text-sm ${
71	            succeeded ? "text-emerald-400" : "text-rose-400"
72	          }`}
73	          role="status"
74	          aria-live="polite"
75	        >
76	          {succeeded && (
77	            <span className="flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/15">
78	              <IconCheck size={11} />
79	            </span>
80	          )}
81	          {result.message}
82	        </p>
83	      )}
84	    </form>
85	  );
86	}
