1	"use server";
2	
3	import { z } from "zod";
4	import { headers } from "next/headers";
5	import { db } from "./db";
6	import { clientIp } from "./rate-limit";
7	import { sendMail } from "./mailer";
8	import { supportEmail } from "./settings";
9	import { escapeHtml } from "./site-render";
10	import { CONTACT_CATEGORIES } from "./contact-categories";
11	
12	/**
13	 * Public /contact form. Each submission is validated, persisted (audit trail +
14	 * per-IP rate limiting), and emailed to the mailbox its category routes to —
15	 * so the message lands in support@ / contact@ / admin@ and shows up in the
16	 * in-portal inbox for that mailbox. Reply-To is the sender, so a team member
17	 * can reply straight from the mailbox.
18	 *
19	 * Never throws: returns a typed result the client renders inline.
20	 */
21	
22	export type ContactResult = {
23	  ok: boolean;
24	  message: string;
25	};
26	
27	const schema = z.object({
28	  name: z.string().trim().min(1, "Please enter your name.").max(120),
29	  email: z.email("That doesn’t look like a valid email.").max(200),
30	  category: z.enum(["support", "bug", "sales", "billing", "general"]),
31	  message: z.string().trim().min(10, "Please add a little more detail (at least 10 characters).").max(5000),
32	});
33	
34	export type ContactInput = {
35	  name: string;
36	  email: string;
37	  category: string;
38	  message: string;
39	  company?: string; // honeypot
40	};
41	
42	/** Derive the mailbox address a category routes to, on the platform's mail domain. */
43	async function routeAddress(box: string): Promise<string> {
44	  const support = await supportEmail(); // e.g. support@nxeon.cloud
45	  const domain = support.includes("@") ? support.split("@")[1] : "nxeon.cloud";
46	  return `${box}@${domain}`;
47	}
48	
49	export async function submitContact(input: ContactInput): Promise<ContactResult> {
50	  // Honeypot tripped — pretend success, send nothing. Bots think they won.
51	  if (typeof input?.company === "string" && input.company.trim()) {
52	    return { ok: true, message: "Thanks — your message is on its way. We’ll get back to you shortly." };
53	  }
54	
55	  const parsed = schema.safeParse({
56	    name: input?.name,
57	    email: typeof input?.email === "string" ? input.email.trim().toLowerCase() : input?.email,
58	    category: input?.category,
59	    message: input?.message,
60	  });
61	
62	  if (!parsed.success) {
63	    const first = parsed.error.issues[0]?.message ?? "Please check the form and try again.";
64	    return { ok: false, message: first };
65	  }
66	
67	  const { name, email, category, message } = parsed.data;
68	
69	  // Attested client IP for rate limiting + the audit row. `clientIp` reads the
70	  // hop nginx actually appended — never the caller-supplied leftmost
71	  // X-Forwarded-For entry, which is free-text a bot rotates to buy a fresh
72	  // allowance every request. Falls back to a shared UNKNOWN bucket, never null.
73	  let ip: string | null = null;
74	  try {
75	    ip = clientIp(await headers());
76	  } catch {
77	    ip = null;
78	  }
79	
80	  // Rate limit: max 5 submissions in 10 minutes from the same IP or email.
81	  try {
82	    const since = new Date(Date.now() - 10 * 60 * 1000);
83	    const recent = await db.contactMessage.count({
84	      where: {
85	        createdAt: { gte: since },
86	        OR: [...(ip ? [{ ip }] : []), { email }],
87	      },
88	    });
89	    if (recent >= 5) {
90	      return { ok: false, message: "You’ve sent a few messages already — please give us a little time to reply before sending more." };
91	    }
92	  } catch {
93	    // If the rate-limit read fails, fail open — don't block a real customer.
94	  }
95	
96	  const routedTo = await routeAddress(CONTACT_CATEGORIES[category].box);
97	  const label = CONTACT_CATEGORIES[category].label;
98	
99	  // Deliver to the routed mailbox. Reply-To = sender so the team replies directly.
100	  const html = `
101	    <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;font-size:15px;color:#0f172a;line-height:1.6">
102	      <p style="margin:0 0 4px"><strong>New ${escapeHtml(label)} enquiry</strong> from the Nxeon contact form.</p>
103	      <table style="border-collapse:collapse;margin:12px 0">
104	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Name</td><td><strong>${escapeHtml(name)}</strong></td></tr>
105	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Email</td><td><a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a></td></tr>
106	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Category</td><td>${escapeHtml(label)}</td></tr>
107	      </table>
108	      <div style="white-space:pre-wrap;border-left:3px solid #6f47f5;padding:8px 14px;background:#f8fafc;border-radius:6px">${escapeHtml(message)}</div>
109	      <p style="margin:16px 0 0;color:#94a3b8;font-size:13px">Reply to this email to respond to ${escapeHtml(name)} directly.</p>
110	    </div>`;
111	
112	  const delivered = await sendMail({
113	    to: routedTo,
114	    replyTo: email,
115	    subject: `[Nxeon · ${label}] ${name}`,
116	    html,
117	  });
118	
119	  // Persist regardless of delivery so nothing is silently lost.
120	  try {
121	    await db.contactMessage.create({
122	      data: { name, email, category, message, routedTo, delivered, ip },
123	    });
124	  } catch (e) {
125	    console.error("[contact] failed to persist message:", e);
126	  }
127	
128	  if (!delivered) {
129	    // The row is saved; an operator can still see it. Tell the user honestly.
130	    return {
131	      ok: true,
132	      message: "Thanks — we’ve received your message and it’s logged with our team. If you don’t hear back soon, email us directly.",
133	    };
134	  }
135	
136	  return {
137	    ok: true,
138	    message: `Thanks, ${name.split(" ")[0]}! Your message is with our ${label.toLowerCase()} team — we’ll reply within one business day.`,
139	  };
140	}
